import React from 'react';
import styled from 'styled-components';

const Services = () => {
    return (
        <div>
            <Title>
                Nasza oferta
            </Title>
            <MainBox>
                <BoxesRow>
                    <ServiceBox>
                        <Subtitle>
                            Ryczałt od przychodów ewidencjonowanych
                        </Subtitle>
                        <table>
                            <tr>
                                <td>
                                    <p>
                                        Kontrola dokumentów pod względem formalno-rachunkowym
                                    </p>
                                </td>
                                <td>
                                    <p>
                                        Kontrola dokumentów pod względem formalno-rachunkowym
                                    </p>
                                </td>
                            </tr>
                        </table>
                    </ServiceBox>
                    <Spacer></Spacer>
                    <ServiceBox>
                        <Subtitle>
                            Podatkowa książka przychodów i rozchodów
                        </Subtitle>
                    </ServiceBox>
                </BoxesRow>
                <BoxesRow>
                    <ServiceBox>
                        <Subtitle>
                            Księgi handlowe
                        </Subtitle>
                    </ServiceBox>
                    <Spacer></Spacer>
                    <ServiceBox>
                        <Subtitle>
                            Kadry i płace
                        </Subtitle>
                    </ServiceBox>
                </BoxesRow>
            </MainBox>
        </div>

    );
}

export default Services

const MainBox = styled.div`
    height: 600px;
    background-color: red;
    margin: 48px;
    margin-left: 80px;
    margin-right: 80px;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
`;

const Title = styled.h1`
    padding-top: 48px;
    padding-bottom: 48px; 
    text-align: center;
`;

const BoxesRow = styled.div`
    display: flex;
    flex-direction: row;
    height: 600px;
    width: 100%;
    align-items: stretch;
    justify-content: center;
`;

const ServiceBox = styled.div`
    flex: 50%;
    border-radius: 25px;
    background-color: #E5A424;
    width: 40%;
    height: auto;
    margin-bottom: 30px;
`;

const Spacer = styled.div`
    flex: 7%;
`;

const Subtitle = styled.h2`
    text-align: center;
    padding: 20px;
    color: #fff;
`;
